def longest_common_prefix(strs):
    strs = list(strs or [])
    if not strs:
        return ''
    first = strs[0]
    for index in range(len(first)):
        ch = first[index]
        for other in strs[1:]:
            if index >= len(other) or other[index] != ch:
                return first[:index]
    return first


print(longest_common_prefix(['flower', 'flow', 'flight']))
print(longest_common_prefix(['dog', 'racecar', 'car']))
